const Module = require('module');
const path = require('path');
const load = Module._load;
const target = path.resolve('core/ExitContractManager');
let refusals = 0;
Module._load = function(request, parent, isMain) {
  const loaded = load.apply(this, arguments);
  if (request !== target) return loaded;
  return { ...loaded, getInstance(...args) {
    const manager = loaded.getInstance(...args);
    return {
      getDefaultContract: manager.getDefaultContract.bind(manager),
      checkExitConditions(trade, ...rest) {
        if (trade && String(trade.id).startsWith('synthetic-smoke-')) {
          refusals++;
          return { shouldExit: false, exitReason: null, details: 'Review-induced refusal for synthetic smoke position' };
        }
        return manager.checkExitConditions(trade, ...rest);
      }
    };
  } };
};
process.on('exit', code => console.log('REVIEW_EXIT_CONTROL=' + JSON.stringify({refusals, exitCode: code})));
